-- Extend notifications to private messages, profile likes, and follows/subscriptions.
-- Notifications are generated by database triggers, never trusted from the browser.

alter table public.notifications drop constraint if exists notifications_notification_type_check;
alter table public.notifications add constraint notifications_notification_type_check
  check (notification_type in ('post_like', 'post_comment', 'private_message', 'profile_like', 'profile_follow'));
alter table public.notifications alter column post_id drop not null;

create or replace function public.iqzodiac_create_private_message_notification()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare v_recipient uuid; v_actor_name text;
begin
  select cp.user_id into v_recipient from public.conversation_participants cp
   where cp.conversation_id = new.conversation_id and cp.user_id <> new.sender_id order by cp.user_id limit 1;
  if v_recipient is null then return new; end if;
  select coalesce(nullif(trim(p.display_name), ''), nullif(trim(p.handle), ''), 'Someone') into v_actor_name
    from public.profiles p where p.user_id = new.sender_id;
  insert into public.notifications (recipient_id, actor_id, notification_type, message)
  values (v_recipient, new.sender_id, 'private_message', coalesce(v_actor_name, 'Someone') || ' sent you a private message.');
  return new;
end;
$$;

create or replace function public.iqzodiac_create_profile_follow_notification()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare v_actor_name text;
begin
  select coalesce(nullif(trim(p.display_name), ''), nullif(trim(p.handle), ''), 'Someone') into v_actor_name
    from public.profiles p where p.user_id = new.follower_id;
  insert into public.notifications (recipient_id, actor_id, notification_type, message)
  values (new.followed_id, new.follower_id, 'profile_follow', coalesce(v_actor_name, 'Someone') || ' started following you.');
  return new;
end;
$$;

create or replace function public.iqzodiac_create_profile_like_notification()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare v_actor_name text;
begin
  if new.user_id = new.candidate_id then return new; end if;
  select coalesce(nullif(trim(p.display_name), ''), nullif(trim(p.handle), ''), 'Someone') into v_actor_name
    from public.profiles p where p.user_id = new.user_id;
  insert into public.notifications (recipient_id, actor_id, notification_type, message)
  values (new.candidate_id, new.user_id, 'profile_like', coalesce(v_actor_name, 'Someone') || ' liked your profile.');
  return new;
end;
$$;

drop trigger if exists private_message_notification_trigger on public.messages;
create trigger private_message_notification_trigger
after insert on public.messages for each row execute function public.iqzodiac_create_private_message_notification();
drop trigger if exists profile_follow_notification_trigger on public.follows;
create trigger profile_follow_notification_trigger
after insert on public.follows for each row execute function public.iqzodiac_create_profile_follow_notification();
drop trigger if exists profile_like_notification_trigger on public.match_likes;
create trigger profile_like_notification_trigger
after insert on public.match_likes for each row execute function public.iqzodiac_create_profile_like_notification();

revoke all on function public.iqzodiac_create_private_message_notification() from public, anon, authenticated;
revoke all on function public.iqzodiac_create_profile_follow_notification() from public, anon, authenticated;
revoke all on function public.iqzodiac_create_profile_like_notification() from public, anon, authenticated;
